<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {api,can} from './session'
const emit=defineEmits(['edit','changed']),rows=ref<any[]>([]),q=ref(''),page=ref(1),pageSize=ref(25),total=ref(0),error=ref(''),loading=ref(false)
async function load(){loading.value=true;try{const d=await api('/logistics/invoices?'+new URLSearchParams({q:q.value,page:String(page.value),page_size:String(pageSize.value)}));rows.value=d.rows;total.value=d.total;error.value=''}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function remove(row:any){try{await ElMessageBox.confirm('删除后，此 FBA 号可以重新生成清关发票。确认删除？','删除清关发票',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'})}catch{return}try{await api(`/logistics/invoices/${row.id}/delete`,{revision:row.revision});await load();emit('changed');ElMessage.success('已删除')}catch(e){ElMessage.error((e as Error).message)}}
const downloadOpen=ref(false),target=ref<any>(),templates=ref<any[]>([]),templateId=ref<number>(),declaration=ref(false),taxMode=ref('自税递延'),downloading=ref(false),downloadError=ref('')
async function download(row:any){target.value=row;templateId.value=undefined;declaration.value=false;taxMode.value='自税递延';downloadError.value='';templates.value=[];downloadOpen.value=true;try{templates.value=(await api('/logistics/templates?kind=invoice')).filter((t:any)=>t.mapping?.sheet)}catch(e){downloadError.value=(e as Error).message}}
async function exportFile(){downloading.value=true;downloadError.value='';try{const d=await api(`/logistics/invoices/${target.value.id}/export`,{revision:target.value.revision,template_id:templateId.value,declaration:declaration.value,tax_mode:taxMode.value});const bytes=Uint8Array.from(atob(d.content),c=>c.charCodeAt(0)),url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),a=document.createElement('a');a.href=url;a.download=d.filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);downloadOpen.value=false;ElMessage.success('Excel 已导出')}catch(e){downloadError.value=(e as Error).message}finally{downloading.value=false}}
const time=(s:string)=>s?new Date(s).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—'
defineExpose({load});onMounted(load)
</script>
<template><section class="clearance-invoices"><div class="invoice-search"><el-input v-model="q" placeholder="搜索 FBA 号" @keyup.enter="page=1;load()"/><el-button @click="page=1;load()">查询</el-button><el-button @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="rows" v-loading="loading" border><el-table-column prop="shipment_id" label="FBA号" min-width="180"/><el-table-column prop="store" label="店铺" min-width="110"/><el-table-column prop="country" label="国家" width="80"/><el-table-column prop="boxes" label="箱数" width="80" align="center"/><el-table-column prop="total_quantity" label="总数量（装箱单）" width="150" align="center"/><el-table-column label="总重量（KG）" width="140" align="center"><template #default="{row}">{{row.weight??'待补齐'}}</template></el-table-column><el-table-column label="预计关税" align="center" min-width="160"><template #default="{row}"><div v-for="(amount,c) in row.estimated_tax" :key="c">{{c}} {{amount??'待补齐'}}</div></template></el-table-column><el-table-column label="发货日期" width="130"><template #default="{row}">{{row.dispatched_on||'待补齐'}}</template></el-table-column><el-table-column prop="actor" label="操作人" width="120"/><el-table-column label="操作日期" width="180"><template #default="{row}">{{time(row.updated_at)}}</template></el-table-column><el-table-column label="操作" fixed="right" width="190"><template #default="{row}"><el-button link type="primary" @click="emit('edit',row)">{{can('fba.invoice','operate')?'编辑':'查看'}}</el-button><el-button v-if="can('fba.invoice','operate')" link type="danger" @click="remove(row)">删除</el-button><el-button v-if="can('fba.invoice','operate')" link type="primary" @click="download(row)">下载</el-button></template></el-table-column></el-table><AppPagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" @change="load"/>
<el-dialog v-model="downloadOpen" title="下载清关发票" width="580px" :close-on-click-modal="!downloading"><el-alert v-if="downloadError" :title="downloadError" type="error" :closable="false"/><el-form label-position="top" :disabled="downloading"><el-form-item label="发票中心模板" required><el-select v-model="templateId" aria-label="选择发票模板" placeholder="选择已配置字段的模板"><el-option v-for="t in templates" :value="t.id" :label="`${t.name} · ${t.supplier||'通用'}`"/></el-select><small v-if="!templates.length">请先在物流中心的发票中心上传模板并配置字段。</small></el-form-item><el-form-item label="是否报关"><el-radio-group v-model="declaration"><el-radio :value="true">报关</el-radio><el-radio :value="false">不报关</el-radio></el-radio-group></el-form-item><el-form-item label="交税方式"><el-radio-group v-model="taxMode"><el-radio value="包税">包税</el-radio><el-radio value="自税递延">自税递延</el-radio></el-radio-group></el-form-item></el-form><template #footer><el-button :disabled="downloading" @click="downloadOpen=false">取消</el-button><el-button type="primary" :disabled="!templateId" :loading="downloading" @click="exportFile">导出 Excel</el-button></template></el-dialog></section></template>
<style scoped>.clearance-invoices{padding:16px;background:white}.invoice-search{display:flex;gap:12px;margin-bottom:16px}.invoice-search .el-input{width:250px}small{display:block;color:#7a8c84}</style>
